                      {Array.from({length:totalPagsCaso},(_,i)=>(
                        <button key={i} onClick={()=>setTabPageCaso(i+1)}
                          style={{ minWidth:26,height:26,borderRadius:4,
                                   border:"1px solid "+(paginaCaso===i+1?C.bordo:C.cinzaL),
                                   background:paginaCaso===i+1?C.bordo:"#fff",
                                   color:paginaCaso===i+1?"#fff":"#374151",
                                   fontSize:11,fontWeight:paginaCaso===i+1?700:400,
                                   cursor:"pointer",padding:"0 6px" }}>{i+1}</button>
                      ))}
